    action = data.get('action', 'load')
    category = data.get('category', '')
    selected = data.get('selected', [])

    conn = get_db_connection()
    try:
        if action == 'load':
            # Get 100 samples from ai_place_name that need review
            where_clause = "WHERE needs_review = 1"
            params = []
            if category:
                where_clause += " AND reason LIKE ?"
                params.append(f'%{category}%')

            rows = conn.execute(f"""
                SELECT dila_id, name_zh, name_vi, source, confidence, needs_review, reason
                FROM ai_place_name
                {where_clause}
                ORDER BY confidence ASC
                LIMIT 100
            """, params).fetchall()

            sample = []
            for r in rows:
                sample.append({
                    'dila_id': r['dila_id'],
                    'name_zh': r['name_zh'] or '',
                    'name_vi': r['name_vi'] or '',
                    'source': r['source'] or '',
