                    'needs_review': r['needs_review'] or 0,
                    'reason': r['reason'] or ''
                })

            return jsonify({
                'success': True,
                'sample': sample,
                'count': len(sample),
                'message': f'Loaded {len(sample)} samples for review'
            })

        elif action == 'approve':
            # Approve selected rows - set needs_review = 0
            if not selected:
                return jsonify({'success': False, 'error': 'No rows selected'}), 400

            updated = 0
            for dila_id in selected:
