            conn.commit()

            return jsonify({
                'success': True,
                'updated': updated,
                'message': f'Approved {updated} rows'
            })

        else:
            return jsonify({'success': False, 'error': 'Invalid action'}), 400

    except Exception as e:
        return jsonify({'success': False, 'error': str(e)}), 500
    finally:
        conn.close()"}

