    if '_active_batches' not in globals():
        _active_batches = {}

    if batch_id and batch_id in _active_batches:
        batch = _active_batches[batch_id]
        # Return last 100 logs
        return jsonify({
            'success': True,
            'batch_id': batch_id,
            'step': batch['step'],
            'status': batch['status'],
            'progress': batch['progress'],
            'total': batch['total'],
            'processed': batch['processed'],
