        batch_id: resp.batch_id,
        total: resp.total
      });
      setMessage({ type: 'success', text: `Batch started: ${resp.total} rows` });
    } catch (e) {
      setMessage({ type: 'error', text: `Lỗi start batch: ${e.message}` });
    } finally {
      setBusy(false);
    }
  };

  // Poll /daoanh/api/admin/batch-monitor every 2s while this step is active
