  // this app.py's Flask setup does not have WS support).
  useEffect(() => {
    if (data.batch_status !== 'running' || !data.batch_id) return undefined;
    let cancelled = false;
    const tick = async () => {
      try {
        const res = await fetch(`${API_BASE}/batch-monitor?batch_id=${data.batch_id}`);
        const json = await res.json();
        if (!cancelled) {
          update({
            progress: json.progress || 0,
            logs: json.logs || [],
            errors: json.errors || [],
            batch_status: json.status || data.batch_status,
            total: json.total || data.total,
            processed: json.processed || 0,
            stats: json.stats || { ok: 0, review: 0, error: 0 }
          });
        }
      } catch (e) { /* network hiccup, keep polling */ }
    };
    tick();
    const id = setInterval(tick, 2000);
    return () => { cancelled = true; clearInterval(id); };
  }, [data.batch_status, data.batch_id]);"}

